    21|// --- MEMORY OPTIMIZATION HELPER ---
    22|// Strips heavy data (CSVs, long markdown) from the dashboard list to prevent
    23|// iOS/iPadOS browser crashes due to memory limits.
    24|const lightenExperiment = (exp: Experiment): Experiment => {
    25|    const lightExp = { ...exp };
    26|    const lightStepData: { [key: number]: any } = {};
    27|
    28|    if (exp.stepData) {
    29|        Object.keys(exp.stepData).forEach(key => {
    30|            const k = Number(key);
    31|            const data = exp.stepData[k];
    32|            lightStepData[k] = {
    33|                ...data,
    34|                // Truncate heavy fields for the list view
    35|                input: data.input ? (data.input.length > 50 ? data.input.substring(0, 50) + '...' : data.input) : undefined,
    36|                output: data.output ? (data.output.length > 50 ? data.output.substring(0, 50) + '...' : data.output) : undefined,
    37|                // Keep summary and blockers as they are essential for UI badges
    38|                summary: data.summary,
    39|                blockers: data.blockers
    40|            };
    41|        });
    42|    }
    43|    lightExp.stepData = lightStepData;
    44|    lightExp.labNotebook = ''; // Clear notebook text from list view
    45|    return lightExp;
    46|};
